export interface ManifestOptions {
  version: string;
}

/** Hosts the extension may call: the deployed server and the local dev server. */
export const SERVER_HOST_PERMISSIONS = [
  'https://tabsync-production.up.railway.app/*',
  'http://localhost:8787/*',
];

/** Generated by `node scripts/make-icons.mjs` into public/icons (copied to dist by Vite). */
export const ICONS = {
  16: 'icons/icon-16.png',
  32: 'icons/icon-32.png',
  48: 'icons/icon-48.png',
  128: 'icons/icon-128.png',
};

export function buildManifest({ version }: ManifestOptions): chrome.runtime.ManifestV3 {
  return {
    manifest_version: 3,
    name: 'Tab Sync',
    description: 'End-to-end encrypted tab, pinned tab and tab group sync between machines.',
    version,
    permissions: ['tabs', 'tabGroups', 'storage', 'alarms', 'favicon'],
    host_permissions: SERVER_HOST_PERMISSIONS,
    // Requested at runtime for the one origin entered as a custom server URL in options.
    optional_host_permissions: ['http://*/*', 'https://*/*'],
    background: { service_worker: 'background.js', type: 'module' },
    icons: ICONS,
    action: {
      default_popup: 'popup.html',
      default_title: 'Set up sync',
      default_icon: { 16: ICONS[16], 32: ICONS[32] },
    },
    options_page: 'options.html',
  };
}
